    /// 🫙 Governing ULS membrane stresses for shells (n_k→σ_x, m_y_k→σ_θ, v_z_k→τ).
    pub fn governing_shell_effects(shell: &crate::snapshot::AluminiumShell, annex: AnnexChoice) -> GoverningEffects {
