pub mod part_1_8 {
    /// 🔩 Bolt tensile stress area from diameter [m] → m² (approx ISO coarse).
    pub fn bolt_as(d: f64) -> f64 {
        let d_mm = d * 1000.0;
        let as_mm2 = match d_mm.round() as i32 {
